import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

public abstract class AbstractAtomProvider<T extends Element> implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods

    @Override
    public T readFrom(Class<T> clazz, Type t, Annotation[] a, MediaType mt,
                      MultivaluedMap<String, String> headers, InputStream is) throws IOException {
        if (is == null) {
            throw new IllegalArgumentException("InputStream cannot be null");
        }

        // Create a fresh ParserOptions instance for each request to avoid
        // race conditions when the shared Parser is used concurrently.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Explicitly disable entity resolution to mitigate XXE attacks.
        options.setResolveEntities(false);

        // Obtain the shared Parser instance but pass the secure options
        // directly to the parse call. This guarantees that the options
        // are applied atomically for this parsing operation.
        Parser parser = ATOM_ENGINE.getParser();
        Document<T> doc = parser.parse(is, options);

        return doc.getRoot();
    }

    // other methods
}
