import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a name derived from {@code name}.
     * The method protects against directory‑traversal attacks by normalising the supplied
     * filename and ensuring that the resulting file resides within {@code dir}. If a file
     * with the same name already exists, a numeric suffix is appended until a unique
     * filename is found.
     *
     * @param dir  the base directory where the file should be created; must not be {@code null}
     * @param name the requested filename; may contain query parameters which are stripped
     * @return a {@link File} instance pointing to a unique file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null}
     * @throws SecurityException        if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory cannot be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("Name cannot be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Normalise the path to eliminate '..', '.' and redundant separators
        Path normalizedPath = Paths.get(name).normalize();

        // Reject absolute paths or paths that navigate outside the base directory
        if (normalizedPath.isAbsolute() || normalizedPath.startsWith("..")) {
            throw new SecurityException("Invalid file name: " + name);
        }

        // Resolve the file against the base directory
        File file = new File(dir, normalizedPath.toString());

        try {
            // Canonicalise to resolve symlinks and ensure containment
            File canonicalDir = dir.getCanonicalFile();
            File canonicalFile = file.getCanonicalFile();

            if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + File.separator)) {
                throw new SecurityException("Attempt to write outside the target directory: " + name);
            }
        } catch (IOException e) {
            // Wrap checked exception into unchecked to preserve original method signature
            throw new RuntimeException("Failed to resolve file path", e);
        }

        // Generate a unique filename if needed
        String baseName = normalizedPath.getFileName().toString();
        int dot = baseName.indexOf('.');
        String prefix = dot < 0 ? baseName : baseName.substring(0, dot);
        String suffix = dot < 0 ? "" : baseName.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods

}
