import java.util.regex.Pattern;

/**
 * A header delegate for {@link javax.ws.rs.core.MediaType} that performs
 * strict validation of the media type's major and minor components.
 *
 * <p>The original implementation performed a limited character blacklist,
 * which left room for HTTP header injection via unfiltered control
 * characters such as CR/LF.  The updated {@code isValid} method now
 * uses a whitelist based on RFC 7230's definition of a <em>token</em>
 * (the allowed characters for media type names).  This guarantees that
 * only safe, non‑control characters are accepted, preventing
 * injection attacks.</p>
 */
public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    /* --------------------------------------------------------------------- */
    /* Validation utilities                                                 */
    /* --------------------------------------------------------------------- */

    /**
     * RFC 7230 § 3.2.6 defines a <em>token</em> as a sequence of one or more
     * characters from the set:
     *
     * <pre>
     * tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" /
     *        "-" / "." / "^" / "_" / "`" / "|" / "~" /
     *        DIGIT / ALPHA
     * </pre>
     *
     * Media type major and minor components must match this pattern.
     * The pattern also allows the single asterisk character (*) which
     * represents a wildcard media type.
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    /**
     * Validates a media type component (major or minor).
     *
     * @param str the component to validate
     * @return {@code true} if {@code str} is a non‑empty token or a single
     *         asterisk; {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Allow the wildcard "*" explicitly
        if ("*".equals(str)) {
            return true;
        }
        // Reject any control characters or whitespace
        if (str.matches(".*[\\x00-\\x1F\\x7F].*")) {
            return false;
        }
        return TOKEN_PATTERN.matcher(str).matches();
    }

    // other methods
}
