private String sanitizeUrl(String url) throws ServletException {
    if (url == null || url.trim().isEmpty()) {
        throw new ServletException("Empty resource URL");
    }
    // Remove leading/trailing whitespace
    url = url.trim();
    // Reject absolute URLs
    if (url.startsWith("/") || url.startsWith("http://") || url.startsWith("https://")) {
        throw new ServletException("Absolute URLs not allowed: " + url);
    }
    // Reject backslashes
    if (url.contains("\\")) {
        throw new ServletException("Backslash in URL not allowed: " + url);
    }
    // Normalize path
    Path path = Paths.get(url).normalize();
    if (path.isAbsolute() || path.toString().contains("..")) {
        throw new ServletException("Path traversal detected in URL: " + url);
    }
    // Reconstruct normalized string
    return path.toString().replace('\\', '/'); // ensure forward slashes
}

