     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to an output stream
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Ensure the target directory exists and obtain its real (canonical) path
        if (!targetDirectory.exists() && !targetDirectory.mkdirs()) {
            throw new IOException("Failed to create target directory: " + targetDirectory);
        }
        final Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Resolve the entry name against the target directory and normalize
            Path entryPath = targetDirPath.resolve(nextEntry.getName()).normalize();

            // Verify that the resolved path is still within the target directory
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + nextEntry.getName() +
                        " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist
                if (!Files.isDirectory(entryPath)) {
                    Files.createDirectories(entryPath);
                }
            } else {
                // Ensure parent directories exist
                Path parent = entryPath.getParent();
                if (parent != null && !Files.isDirectory(parent)) {
                    Files.createDirectories(parent);
                }

                // Write the file contents
                try (OutputStream out = Files.newOutputStream(entryPath)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
