     */
    @Override
    @Nonnull
    public String getValidHref(final String url) {
        if (!StringUtils.isNotBlank(url)) {
            return "";
        }

        try {
            // Trim whitespace and build a URI instance
            URI uri = new URI(url.trim());

            // Reject dangerous schemes
            String scheme = uri.getScheme();
            if (scheme != null) {
                String lowerScheme = scheme.toLowerCase(Locale.ENGLISH);
                if (!lowerScheme.equals("http")
                        && !lowerScheme.equals("https")
                        && !lowerScheme.equals("mailto")) {
                    return "";
                }
            } else {
                // For relative URLs, still guard against javascript:/data: prefixes
                String lower = url.toLowerCase(Locale.ENGLISH);
                if (lower.startsWith("javascript:") || lower.startsWith("data:")) {
                    return "";
                }
            }

            // Convert to an ASCII representation which percent‑encodes unsafe characters
            String sanitized = uri.toASCIIString();

            // Escape characters that are problematic in HTML attribute contexts
            sanitized = StringEscapeUtils.escapeHtml4(sanitized);

            // Final validation using the framework's XSS filter
            if (xssFilter.isValidHref(sanitized)) {
                return sanitized;
            }
        } catch (URISyntaxException e) {
            LOGGER.warn("Invalid URL syntax: {}", url, e);
        } catch (UnsupportedEncodingException e) {
            // This exception cannot occur with UTF-8, but keep for compatibility
            LOGGER.error("Unable to decode url: {}", url, e);
        }

        return "";
